const fs = require("fs");
function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
(async () => {
  const tw = require("tailwindcss");
  const css = fs.readFileSync("/w/node_modules/tailwindcss/index.css", "utf8");
  const ds = await tw.__unstable__loadDesignSystem(css, { base: "/tmp" });
  if (!ds || typeof ds.canonicalizeCandidates !== "function") broken("design system has no canonicalizeCandidates");
  const got = ds.canonicalizeCandidates(["scroll-pt-4", "scroll-pb-4"], { collapse: true }).join(" ");
  if (got === "scroll-py-4") { console.log("OK: scroll-pt-4 scroll-pb-4 canonicalizes to scroll-py-4"); return; }
  if (got === "scroll-pt-4 scroll-pb-4" || got === "scroll-pb-4 scroll-pt-4") symptom("canonicalizeCandidates does not collapse scroll-pt-4 scroll-pb-4 into scroll-py-4");
  broken("unexpected canonicalization: " + got);
})().catch((e) => broken(String((e && e.stack) || e)));

